class Shape:
    def area(self):
        raise NotImplementedError("Subclasses should implement this method")

class Square(Shape):
    def area(self):
        return math.pow(self.length, 2)

class Circle(Shape):
    def area(self):
        return math.pi * math.pow(self.radius, 2)

